package com.bank.recover;

import java.util.*;
import java.util.logging.Logger;

// S3-style versioned state: every save is a version; delete can be undone by restore.
public class VersionedStateStore {
    private static final Logger log = Logger.getLogger(VersionedStateStore.class.getName());
    private final List<Set<String>> versions = new ArrayList<>();
    private Set<String> current = new LinkedHashSet<>();
    private boolean deleted = false;

    public void save() { versions.add(new LinkedHashSet<>(current)); log.info(() -> "state saved as version " + versions.size()); }
    public void record(String resource) { current.add(resource); }
    public boolean has(String resource) { return !deleted && current.contains(resource); }

    public void delete() { deleted = true; current = new LinkedHashSet<>(); log.severe("STATE DELETED — Terraform now thinks nothing exists!"); }

    public void restore(int version) {
        current = new LinkedHashSet<>(versions.get(version - 1));
        deleted = false;
        log.info(() -> "restored state from version " + version + " -> " + current);
    }
    public Set<String> current() { return new LinkedHashSet<>(current); }
    public int versionCount() { return versions.size(); }
}
