package com.bank.recover;

import java.util.*;
import java.util.logging.Logger;

// Applies in order, recording each success. Can fail midway (quota, etc.).
public class StatefulApply {
    private static final Logger log = Logger.getLogger(StatefulApply.class.getName());
    private final VersionedStateStore state;

    public StatefulApply(VersionedStateStore state) { this.state = state; }

    // failAt = resource name that fails; null = all succeed
    public boolean apply(List<String> desired, String failAt) {
        for (String r : desired) {
            if (state.has(r)) { log.info(() -> "skip " + r + " (already in state)"); continue; }
            if (r.equals(failAt)) {
                log.severe(() -> "apply FAILED at " + r + " (quota exceeded) — partial state persisted");
                state.save();  // partial state saved: earlier resources recorded
                return false;
            }
            state.record(r);
            log.info(() -> "created + recorded " + r);
        }
        state.save();
        log.info("apply complete");
        return true;
    }
}
