package com.bank.recover;

import java.util.*;
import java.util.logging.Logger;

// Recovery toolkit: restore-from-version, import untracked, targeted apply.
public class Recovery {
    private static final Logger log = Logger.getLogger(Recovery.class.getName());
    private final VersionedStateStore state;

    public Recovery(VersionedStateStore state) { this.state = state; }

    public void restoreFromVersion(int version) {
        log.info(() -> "RECOVERY: restore state object version " + version + " (S3 versioning)");
        state.restore(version);
    }
    public void importResource(String resource) {
        log.info(() -> "RECOVERY: terraform import " + resource + " (no backup -> rebuild state)");
        state.record(resource);
    }
    public void targetedApply(StatefulApply apply, String resource) {
        log.info(() -> "RECOVERY: terraform apply -target=" + resource + " (repair ONLY this resource)");
        apply.apply(List.of(resource), null);
    }
}
