package com.bank.recover;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class RecoveryDemo {
    private static final Logger log = Logger.getLogger(RecoveryDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        VersionedStateStore state = new VersionedStateStore();
        StatefulApply apply = new StatefulApply(state);
        Recovery recovery = new Recovery(state);

        List<String> infra = List.of("aws_vpc.bank", "aws_eks_cluster.bank", "aws_db_instance.ledger");

        // Full apply creates infra + versioned state
        apply.apply(infra, null);

        // DISASTER 1: state object deleted -> restore from version
        state.delete();
        recovery.restoreFromVersion(state.versionCount());   // promote last good version
        apply.apply(infra, null);  // plan shows NOTHING to create -> recovered, no duplicates

        // DISASTER 2: apply a read-replica, fail midway at the replica
        List<String> expansion = List.of("aws_subnet.replica_net", "aws_db_instance.replica");
        apply.apply(expansion, "aws_db_instance.replica");   // subnet created, replica fails
        log.info("partial state now: " + state.current());
        // raise quota, then targeted apply repairs ONLY the replica
        recovery.targetedApply(apply, "aws_db_instance.replica");

        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on recovered ledger infrastructure");
    }
}
